    assert generate_k_combinations([], 0) == [[]]
    assert generate_k_combinations([1, 2, 3], 0) == [[]]

def test_generate_k_combinations_single_element():
    assert generate_k_combinations([5], 1) == [[5]]
    assert generate_k_combinations([1, 2, 3], 1) == [[1], [2], [3]]

