from solution import extract_keywords

def test_extract_keywords_basic():
    text = "Hello, world! Programming in Python is fun. Python is easy to learn."
    stopwords = ["is", "in", "to"]
    expected_output = {'hello': 1, 'world': 1, 'programming': 1, 'python': 2, 'fun': 1, 'easy': 1, 'learn': 1}
    assert extract_keywords(text, stopwords) == expected_output

def test_extract_keywords_with_stopwords():
    text = "This is a test. This test is simple."
    stopwords = ["is", "a"]
    expected_output = {'this': 2, 'test': 2, 'simple': 1}
    assert extract_keywords(text, stopwords) == expected_output

def test_extract_keywords_empty_string():
    text = ""
    stopwords = ["is", "in", "to"]
    expected_output = {}
    assert extract_keywords(text, stopwords) == expected_output

def test_extract_keywords_no_stopwords():
    text = "Data analysis is crucial for a business."
    stopwords = []
    expected_output = {'data': 1, 'analysis': 1, 'is': 1, 'crucial': 1, 'for': 1, 'a': 1, 'business': 1}
    assert extract_keywords(text, stopwords) == expected_output

def test_extract_keywords_all_stopwords():
    text = "Machine learning is a subset of artificial intelligence."
    stopwords = ["machine", "learning", "is", "a", "subset", "of", "artificial", "intelligence"]
    expected_output = {}
    assert extract_keywords(text, stopwords) == expected_output

def test_extract_keywords_with_repeated_keywords():
    text = "Cats and dogs are popular pets. Cats are often independent."
    stopwords = ["and", "are"]
    expected_output = {'cats': 2, 'dogs': 1, 'popular': 1, 'pets': 1, 'often': 1, 'independent': 1}
    assert extract_keywords(text, stopwords) == expected_output

