def test_modifyDataset_basic():
    df = pd.DataFrame({
        'fruit': ['apple', 'banana', 'apple'], 
        'color': ['green', 'red', 'yellow']
    })

    modified_df = modifyDataset(df)

    expected_df = pd.DataFrame({
        'fruit': ['orange', 'banana', 'orange'], 
        'color': ['yellow', 'red', 'yellow']
    })

    pd.testing.assert_frame_equal(modified_df, expected_df)

def test_modifyDataset_no_changes():
    df = pd.DataFrame({
        'fruit': ['banana', 'grape', 'orange'], 
        'color': ['blue', 'red', 'yellow']
    })

    modified_df = modifyDataset(df)

    expected_df = pd.DataFrame({
        'fruit': ['banana', 'grape', 'orange'], 
        'color': ['blue', 'red', 'yellow']
    })

    pd.testing.assert_frame_equal(modified_df, expected_df)

def test_modifyDataset_partial_change():
    df = pd.DataFrame({
        'fruit': ['apple', 'banana', 'orange'], 
        'color': ['green', 'green', 'red']
    })

    modified_df = modifyDataset(df)

    expected_df = pd.DataFrame({
        'fruit': ['orange', 'banana', 'orange'], 
        'color': ['yellow', 'yellow', 'red']
    })

    pd.testing.assert_frame_equal(modified_df, expected_df)

def test_modifyDataset_raises_exception():
    df = pd.DataFrame({
        'fruit': ['apple', 'banana', 'apple'],
        'color': ['green', 'red', 'yellow']
    })

    # Creating a scenario where an error will be raised by removing the 'color' column
    df.drop(columns=['color'], inplace=True)

    try:
        modifyDataset(df)
    except Exception:
        # If an error is raised, this is expected in this test
        pass

    # Since changes should be rolled back, the df should not be modified
    assert 'color' not in df.columns

def test_modifyDataset_unexpected_change():
    df = pd.DataFrame({
        'fruit': ['apple', 'banana', 'apple'], 
        'color': ['cyan', 'red', 'magenta']
    })

    modified_df = modifyDataset(df)

    expected_df = pd.DataFrame({
        'fruit': ['orange', 'banana', 'orange'], 
        'color': ['cyan', 'red', 'magenta']
    })

    pd.testing.assert_frame_equal(modified_df, expected_df)

