        "win": 2.0,
        "free": 1.5,
        "iphone": 3.0,
        "don't miss": 2.5,
        "opportunity": 1.8,
        "earn": 2.2,
        "money": 3.5,
        "easily": 1.0
    }
    expected_scores = {
        "Win a free iPhone now!": 6.5,
