from solution import generate_password

def test_generate_password_invalid_length():
    assert generate_password(5) == "Invalid length"
    assert generate_password(17) == "Invalid length"

def test_generate_password_valid_length():
    for length in range(8, 17):
        password = generate_password(length)
        assert len(password) == length
        assert any(c.islower() for c in password)
        assert any(c.isupper() for c in password)
        assert any(c.isdigit() for c in password)
        assert any(c in "!@#$%^&*()-_=+[]{}|;:,.<>?/" for c in password)
        assert isinstance(password, str)

def test_generate_password_randomness():
    passwords = {generate_password(12) for _ in range(10)}
    assert len(passwords) > 1  # There's a high probability passwords are different

